import unittest
from unittest.mock import patch

from tmc import points
from tmc.utils import load_module, reload_module, get_stdout, assert_ignore_ws

exercise = 'src.name_and_age'

def parse_result(output):
    if len(output) > 30:
        return output[:30] + "..."
    else:
        return output

@points('1.name_and_age')
class NameAndAgeTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        with patch('builtins.input', return_value = '0'):
            cls.module = load_module(exercise, 'en')

    def test_frances_fictitous(self):
        with patch('builtins.input', side_effect = [ 'Frances Fictitous', '1990', AssertionError("Input is asked too many times.") ]) as prompt:
            reload_module(self.module)
            output = get_stdout()
            self.assertTrue(len(output)>0, 'Your program does not print anything' )
            e = 'Hi Frances Fictitous, you will be 31 years old at the end of the year 2021'
            assert_ignore_ws(self, output, e, "When input is Frances Fictitous 1990\n", 'en')

    def test_other_names_1(self):
        testset = [
            ['Paul Python', '2020', '1'],
        ]
        for name, born, age in testset:
            with patch('builtins.input', side_effect = [name, born]):
                reload_module(self.module)
                output = get_stdout()
                e = f"Hi {name}, you will be {age} years old at the end of the year 2021"
                assert_ignore_ws(self, output, e, f"When input is {name} {born}\n", 'en')

    def test_other_names_2(self):
        testset = [
            ['Angela Merkel', '1954', '67'],
        ]
        for name, born, age in testset:
            with patch('builtins.input', side_effect = [name, born]):
                reload_module(self.module)
                output = get_stdout()
                e = f"Hi {name}, you will be {age} years old at the end of the year 2021"
                assert_ignore_ws(self, output, e, f"When input is {name} {born}\n", 'en')

    def test_other_names_3(self):
        testset = [
            ['Wendy Rose', '2013', '8'],
        ]
        for name, born, age in testset:
            with patch('builtins.input', side_effect = [name, born]):
                reload_module(self.module)
                output = get_stdout()
                e = f"Hi {name}, you will be {age} years old at the end of the year 2021"
                assert_ignore_ws(self, output, e, f"When input is {name} {born}\n", 'en')

if __name__ == '__main__':
    unittest.main()

import unittest
from unittest.mock import patch

from tmc import points
from tmc.utils import load_module, reload_module, get_stdout

exercise = 'src.seconds_in_a_day'

def parse_result(output):
    if len(output) > 30:
        return output[:30] + "..."
    else:
        return output

@points('1.seconds_in_a_day')
class SecondsInADayTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        with patch('builtins.input', return_value = '0'):
            cls.module = load_module(exercise, 'en')

    def test_1_seconds_in_one_day(self):
        with patch('builtins.input', return_value = '1'):
            reload_module(self.module)
            result = get_stdout()
            self.assertTrue(len(result)>0, 'Your program does not print anything' )
            self.assertTrue('86400' in result.split(), '1 day is 86400 seconds. Your program\'s output was: ' + parse_result(result))

    def test_2_seconds_in_seven_days(self):
        with patch('builtins.input', return_value = '7'):
            reload_module(self.module)
            result = get_stdout()
            self.assertTrue('604800' in result.split(), '7 days is 604800 seconds. Your program\'s output was: ' + parse_result(result))


    def test_3_additional_tests(self):
        testset = [
            ['0', '0'],
            ['13', '1123200'],
            ['51', '4406400'],
            ['110', '9504000'],
            ['2020', '174528000']
        ]
        for days, seconds in testset:
            with patch('builtins.input', return_value = days):
                reload_module(self.module)
                self.assertTrue(seconds in get_stdout().split(), 'Output is incorrect with input ' + days + '. ' + days + ' days is ' + seconds + ' seconds.')

if __name__ == '__main__':
    unittest.main()
